const VARIANT_BASE = {
  en_us: 'en', en_uk: 'en',
  es_es: 'es', es_la: 'es',
  pt_br: 'pt',
  fr_ca: 'fr',
  zh_cn: 'zh',
};

const I18N = Object.assign({}, BASE_I18N);
for (const [variant, base] of Object.entries(VARIANT_BASE)) {
  I18N[variant] = Object.assign({}, BASE_I18N[base], VARIANT_OVERRIDES[variant] || {});
}

const BCP47_TO_CODE = {
  'en-us': 'en_us', 'en-gb': 'en_uk', 'en-uk': 'en_uk',
  'es-es': 'es_es', 'es-419': 'es_la', 'es-mx': 'es_la', 'es-ar': 'es_la', 'es-co': 'es_la', 'es-cl': 'es_la', 'es-pe': 'es_la', 'es-ve': 'es_la',
  'pt-br': 'pt_br', 'pt-pt': 'pt',
  'fr-ca': 'fr_ca', 'fr-fr': 'fr',
  'zh-cn': 'zh_cn', 'zh-hans': 'zh_cn', 'zh-sg': 'zh_cn',
  'zh-tw': 'zh_tw', 'zh-hant': 'zh_tw',
  'zh-hk': 'yue', 'zh-mo': 'yue', 'yue': 'yue', 'yue-hk': 'yue', 'yue-hant-hk': 'yue',
  'nb': 'no', 'nn': 'no', 'nb-no': 'no', 'nn-no': 'no',
  'fil': 'tl', 'fil-ph': 'tl', 'tl-ph': 'tl',
};

function resolveUiLang(acceptLangHeader, explicitLang) {
  const clean = (v) => String(v || '').trim().toLowerCase().replace(/_/g, '-');
  const tryTag = (raw) => {
    const tag = clean(raw);
    if (!tag || tag === 'auto') return null;
    const under = tag.replace(/-/g, '_');
    if (I18N[under]) return under;
    if (BCP47_TO_CODE[tag] && I18N[BCP47_TO_CODE[tag]]) return BCP47_TO_CODE[tag];
    const parts = tag.split('-');
    if (parts.length >= 2) {
      const two = parts[0] + '-' + parts[1];
      if (BCP47_TO_CODE[two] && I18N[BCP47_TO_CODE[two]]) return BCP47_TO_CODE[two];
    }
    if (I18N[parts[0]]) return parts[0];
    if (BCP47_TO_CODE[parts[0]] && I18N[BCP47_TO_CODE[parts[0]]]) return BCP47_TO_CODE[parts[0]];
    return null;
  };
  const direct = tryTag(explicitLang);
  if (direct) return direct;
  const header = String(acceptLangHeader || '');
  if (header) {
    const items = header.split(',').map((part, idx) => {
      const segs = part.trim().split(';');
      const tag = segs[0].trim();
      let q = 1;
      for (let i = 1; i < segs.length; i++) {
        const m = segs[i].trim().match(/^q=([0-9.]+)$/i);
        if (m) q = parseFloat(m[1]);
      }
      return { tag, q: Number.isFinite(q) ? q : 0, idx };
    }).filter(x => x.tag && x.q > 0).sort((a, b) => (b.q - a.q) || (a.idx - b.idx));
    for (const it of items) {
      const hit = tryTag(it.tag);
      if (hit) return hit;
    }
  }
  return 'en';
}

module.exports = { UI_LANG_META, BASE_I18N, I18N, resolveUiLang };
